      ]}]
    }
  ]
}
json.dump(baseline, open('baseline-packages.json','w'), indent=2)

after = json.load(open('after-cpm-packages.json'))
# Compare resolved versions
def get_versions(data):
    result = {}
    for p in data['projects']:
        for fw in p['frameworks']:
            for pkg in fw['topLevelPackages']:
                result[pkg['id']] = pkg['resolvedVersion']
    return result

b = get_versions(baseline)
a = get_versions(after)
if b == a:
    print('IDENTICAL - all package versions match')
else:
    print('DIFFERENCES:')
    for k in sorted(set(list(b.keys()) + list(a.keys()))):
        if b.get(k) != a.get(k):
            print(f'  {k}: {b.get(k)} -> {a.get(k)}')
